paramConversion.applyStepsToNormalizedParameterValue:
function applyStepsToNormalizedParameterValue(normalizedValue, steps) {
    if (steps == 1) {
        if (normalizedValue > 0) {
            normalizedValue = 1.;
        }
    } else {
        let oneStep = 1. / (steps - 1);
        let numberOfSteps = rnbo_fround(normalizedValue / oneStep * 1 / 1) * 1;
        normalizedValue = numberOfSteps * oneStep;
    }

    return normalizedValue;
}

paramConversion.convertToNormalizedParameterValue:
function convertToNormalizedParameterValue(index, value) {
    switch (index) {
    case 1:
    case 7:
        {
            value = (value < 0 ? 0 : (value > 1 ? 1 : value));
            let normalizedValue = (value - 0) / (1 - 0);
            return normalizedValue;
        }
    case 0:
        {
            value = (value < 0 ? 0 : (value > 3 ? 3 : value));
            let normalizedValue = (value - 0) / (3 - 0);

            {
                normalizedValue = this.applyStepsToNormalizedParameterValue(normalizedValue, 4);
            }

            return normalizedValue;
        }
    case 4:
        {
            value = (value < 0 ? 0 : (value > 10 ? 10 : value));
            let normalizedValue = (value - 0) / (10 - 0);
            return normalizedValue;
        }
    case 8:
        {
            value = (value < 0 ? 0 : (value > 6000 ? 6000 : value));
            let normalizedValue = (value - 0) / (6000 - 0);
            return normalizedValue;
        }
    case 10:
    case 11:
        {
            value = (value < 0 ? 0 : (value > 0.999 ? 0.999 : value));
            let normalizedValue = (value - 0) / (0.999 - 0);
            return normalizedValue;
        }
    case 3:
    case 9:
        {
            value = (value < 1 ? 1 : (value > 2000 ? 2000 : value));
            let normalizedValue = (value - 1) / (2000 - 1);
            return normalizedValue;
        }
    case 6:
        {
            value = (value < 1 ? 1 : (value > 3000 ? 3000 : value));
            let normalizedValue = (value - 1) / (3000 - 1);
            return normalizedValue;
        }
    case 2:
        {
            value = (value < 30 ? 30 : (value > 10000 ? 10000 : value));
            let normalizedValue = (value - 30) / (10000 - 30);
            return normalizedValue;
        }
    case 5:
        {
            value = (value < 0.5 ? 0.5 : (value > 1000 ? 1000 : value));
            let normalizedValue = (value - 0.5) / (1000 - 0.5);
            return normalizedValue;
        }
    default:
        return value;
    }
}

paramConversion.convertFromNormalizedParameterValue:
function convertFromNormalizedParameterValue(index, value) {
    value = (value < 0 ? 0 : (value > 1 ? 1 : value));

    switch (index) {
    case 1:
    case 7:
        {
            {
                return 0 + value * (1 - 0);
            }
        }
    case 0:
        {
            {
                value = this.applyStepsToNormalizedParameterValue(value, 4);
            }

            {
                return 0 + value * (3 - 0);
            }
        }
    case 4:
        {
            {
                return 0 + value * (10 - 0);
            }
        }
    case 8:
        {
            {
                return 0 + value * (6000 - 0);
            }
        }
    case 10:
    case 11:
        {
            {
                return 0 + value * (0.999 - 0);
            }
        }
    case 3:
    case 9:
        {
            {
                return 1 + value * (2000 - 1);
            }
        }
    case 6:
        {
            {
                return 1 + value * (3000 - 1);
            }
        }
    case 2:
        {
            {
                return 30 + value * (10000 - 30);
            }
        }
    case 5:
        {
            {
                return 0.5 + value * (1000 - 0.5);
            }
        }
    default:
        return value;
    }
}

paramConversion.constrainParameterValue:
function constrainParameterValue(index, value) {
    var v = value;

    switch (index) {
    case 0:
        {
            v = (v > 3 ? 3 : (v < 0 ? 0 : v));

            {
                const oneStep = 3 / 3;
                const oneStepInv = (oneStep != 0 ? 1 / oneStep : 0);
                const numberOfSteps = rnbo_fround((v - 0) * oneStepInv * 1 / 1) * 1;
                v = numberOfSteps * oneStep + 0;
            }

            return v;
        }
    case 1:
        {
            v = (v > 1 ? 1 : (v < 0 ? 0 : v));
            return v;
        }
    case 2:
        {
            v = (v > 10000 ? 10000 : (v < 30 ? 30 : v));
            return v;
        }
    case 3:
        {
            v = (v > 2000 ? 2000 : (v < 1 ? 1 : v));
            return v;
        }
    case 4:
        {
            v = (v > 10 ? 10 : (v < 0 ? 0 : v));
            return v;
        }
    case 5:
        {
            v = (v > 1000 ? 1000 : (v < 0.5 ? 0.5 : v));
            return v;
        }
    case 6:
        {
            v = (v > 3000 ? 3000 : (v < 1 ? 1 : v));
            return v;
        }
    case 7:
        {
            v = (v > 1 ? 1 : (v < 0 ? 0 : v));
            return v;
        }
    case 8:
        {
            v = (v > 6000 ? 6000 : (v < 0 ? 0 : v));
            return v;
        }
    case 9:
        {
            v = (v > 2000 ? 2000 : (v < 1 ? 1 : v));
            return v;
        }
    case 10:
        {
            v = (v > 0.999 ? 0.999 : (v < 0 ? 0 : v));
            return v;
        }
    case 11:
        {
            v = (v > 0.999 ? 0.999 : (v < 0 ? 0 : v));
            return v;
        }
    default:
        return value;
    }
}
